import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { getEnv } from '@/lib/env';

/**
 * Local media storage. Files live outside /public and are only served through the
 * /media route, which applies visibility and ownership rules. Keys are generated by the
 * server; user-supplied filenames are never used.
 *
 * Production: point MEDIA_DIR at a persistent volume, or replace this module with an
 * S3-compatible adapter that exposes the same four functions.
 */

export type Variant = 'lg' | 'sm';
const KEY_PATTERN = /^[a-z0-9]{20,40}\/[a-f0-9]{32}$/;

export function isValidStorageKey(key: string): boolean {
  return KEY_PATTERN.test(key);
}

function root(): string {
  return path.resolve(process.cwd(), getEnv().MEDIA_DIR);
}

export function variantPath(key: string, variant: Variant): string {
  if (!isValidStorageKey(key)) throw new Error('Invalid storage key');
  const full = path.resolve(root(), `${key}-${variant}.webp`);
  if (!full.startsWith(root() + path.sep)) throw new Error('Path escapes media root');
  return full;
}

/** Builds a new key for a property image. The id part is random, so it cannot be guessed or enumerated. */
export function newStorageKey(propertyId: string, randomHex: string): string {
  return `${propertyId}/${randomHex}`;
}

export async function writeVariants(key: string, large: Buffer, thumb: Buffer): Promise<void> {
  await mkdir(path.dirname(variantPath(key, 'lg')), { recursive: true });
  await writeFile(variantPath(key, 'lg'), large, { flag: 'wx' });
  await writeFile(variantPath(key, 'sm'), thumb, { flag: 'wx' });
}

export async function readVariant(key: string, variant: Variant): Promise<Buffer> {
  return readFile(variantPath(key, variant));
}

/** Removes both variants. Missing files are ignored so cleanup is idempotent. */
export async function removeVariants(key: string): Promise<void> {
  for (const v of ['lg', 'sm'] as const) {
    await rm(variantPath(key, v), { force: true });
  }
}
